    "settings.diagnostics.providerRequestTrace.description": "开启后，后台会把同一逻辑 Provider 请求及其每次真实重试记录到同一组中，保存最终线上请求、响应元数据、解析前原始返回、chunk 或 WebSocket 帧边界以及失败终态。所属会话的 temp/provider-api-trace 目录固定轮转 4 个逻辑请求槽位；每次尝试最多保留 64 MiB 原始返回，失败和手动终止时已收到的部分内容也不会丢弃。VCE 批量向量任务会另存精确请求文件及供应商返回的完整 output/error 文件，位于应用数据目录的 temp/vce 下，按项目和任务隔离，不自动轮转。文件可能包含提示词、代码内容、工具参数、工具结果与 Provider 原文，仅应在诊断期间开启。",
